def transform(grid):
    h, w = len(grid), len(grid[0])
    orange = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 4]
    guide = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 6]
    out = [row[:] for row in grid]
    if not orange or not guide:
        return out
    r0, r1 = min(r for r, c in orange), max(r for r, c in orange)
    c0, c1 = min(c for r, c in orange), max(c for r, c in orange)
    gr0, gr1 = min(r for r, c in guide), max(r for r, c in guide)
    gc0, gc1 = min(c for r, c in guide), max(c for r, c in guide)
    gh, gw = gr1 - gr0 + 1, gc1 - gc0 + 1
    if gh >= gw:
        if (gc0 + gc1) / 2 < (c0 + c1) / 2:
            for r, c in orange:
                cc = 2 * c0 - 1 - c
                if 0 <= cc < w:
                    out[r][cc] = 4
        else:
            for r, c in orange:
                cc = 2 * c1 + 1 - c
                if 0 <= cc < w:
                    out[r][cc] = 4
    else:
        if (gr0 + gr1) / 2 < (r0 + r1) / 2:
            for r, c in orange:
                rr = 2 * r0 - 1 - r
                if 0 <= rr < h:
                    out[rr][c] = 4
        else:
            for r, c in orange:
                rr = 2 * r1 + 1 - r
                if 0 <= rr < h:
                    out[rr][c] = 4
    for r, c in guide:
        out[r][c] = 0
    return out
